// Block (composition) — sign-in through other services: one Button per provider in that provider's own colour and mark, then optionally "or" and another way in
//
// Each provider's colour, ink and mark are the caller's, passed straight to Button's `provider`
// variant: the design system ships no third party's colour, mark or name. The caller owns each
// pair's 4.5:1, as Button states. The other way in (an email form, a "look around first" link) goes
// in `children`, under the "or" rule; with no children there is no rule. It arranges Buttons,
// Separators and Stack, and paints nothing of its own.
import { useId } from "react";
import type { ReactNode, Ref } from "react";
import { Text } from "react-aria-components";
import { Button } from "../components/Button";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./SocialLogin.css";

export interface SocialLoginProvider {
  /** Passed back to `onSelect`. */
  id: string;
  /** The button's label, e.g. "Continue with Provider A". */
  label: string;
  /** The provider's fill, as a CSS colour; the same in every theme. */
  color: string;
  /** The label and mark ink on `color`, clearing 4.5:1 against it. */
  foreground: string;
  /** The provider's mark, drawn before the label in `currentColor` or its own colours. Decorative. */
  mark?: ReactNode;
}

export interface SocialLoginProps {
  /** A section label above the buttons. None by default: the page names itself. */
  heading?: string;
  /** One button per provider, in this order. */
  providers: SocialLoginProvider[];
  /** Called with the pressed provider's `id`. */
  onSelect?: (id: string) => void;
  /** The provider being signed in to: its button pends and the others stay pressable. */
  pendingId?: string;
  /**
   * The word on the rule between the providers and `children`.
   *
   * @default "or"
   */
  dividerLabel?: string;
  /** Another way in, under the rule: an email form, a link to browse first. */
  children?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SocialLogin({
  heading,
  providers,
  onSelect,
  pendingId,
  dividerLabel = "or",
  children,
  className,
  ref,
}: SocialLoginProps) {
  const headingId = useId();
  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-labelledby={heading ? headingId : undefined}
      className={className ? `sd-sociallogin ${className}` : "sd-sociallogin"}
    >
      {heading && (
        <h2 id={headingId} className="sd-sociallogin__heading sd-type-title-medium">
          {heading}
        </h2>
      )}
      <Stack gap="x-small" className="sd-sociallogin__providers">
        {providers.map((provider) => (
          <Button
            key={provider.id}
            variant="provider"
            providerColor={provider.color}
            providerForeground={provider.foreground}
            isPending={pendingId === provider.id}
            onPress={() => onSelect?.(provider.id)}
          >
            {provider.mark}
            <Text>{provider.label}</Text>
          </Button>
        ))}
      </Stack>
      {children != null && (
        <>
          <Stack direction="row" align="center" gap="small" className="sd-sociallogin__divider">
            <Separator isDecorative className="sd-sociallogin__rule" />
            <span className="sd-sociallogin__divider-label sd-type-caption-medium">{dividerLabel}</span>
            <Separator isDecorative className="sd-sociallogin__rule" />
          </Stack>
          {children}
        </>
      )}
    </Stack>
  );
}

/* SocialLogin.css — .sd-sociallogin (Block)
   Arrangement only: Stack places the heading, the provider Buttons and the "or" rule; Button and
   Separator own every look. Fills the column it is given. No new tokens. */
.sd-sociallogin {
  width: 100%;
}

.sd-sociallogin__heading {
  margin: 0;
}

/* The two rules share the row the word leaves them. */
.sd-sociallogin__rule {
  flex-grow: 1;
  flex-basis: 0;
}

/* A supporting word between two ways in (naming-convention § Text colour roles, row 4). */
.sd-sociallogin__divider-label {
  color: var(--sd-color-text-muted);
}
